```javascript
const axios = require("axios");

async function getData(link) {
  try {
    const response = await axios.post(
      "https://api.vidssave.com/api/contentsite_api/media/parse",
      "auth=20250901majwlqo&domain=api-ak.vidssave.com&origin=source&link=" + encodeURIComponent(link),
      {
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "User-Agent": "Mozilla/5.0 (Linux; Android 12; Infinix X665E Build/SP1A.210812.016; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/150.0.7871.181 Mobile Safari/537.36",
          "Referer": "https://id.vidssave.com/home-1ey"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://youtu.be/Ys7-6_t7OEQ?si=iQdzNlOaD0REbHkg")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
